changeSet.sql:
ALTER TABLE aviso_correo ADD CONSTRAINT ck_aviso_correo_tipo CHECK (
    notification_type IN ('NEW_INCIDENT_ALERT','STATUS_CHANGE_ALERT','CREDENTIAL_ISSUED','PASSWORD_RESET')
)

ALTER TABLE aviso_correo ADD CONSTRAINT ck_aviso_correo_status CHECK (
    status IN ('PENDIENTE','ENVIANDO','ENVIADO','FALLIDO','DESCARTADO','SUPRIMIDO')
)

ALTER TABLE aviso_correo ADD CONSTRAINT ck_aviso_correo_attempt_count CHECK (
    attempt_count >= 0
)

ALTER TABLE aviso_correo ADD CONSTRAINT ck_aviso_correo_max_attempts CHECK (
    max_attempts >= 1
)

ALTER TABLE aviso_correo ADD CONSTRAINT ck_aviso_correo_intentos CHECK (
    attempt_count <= max_attempts
)

ALTER TABLE aviso_correo ADD CONSTRAINT ck_aviso_correo_motivo_sup CHECK (
    suppression_reason_code IN ('USUARIO_DESACTIVADO','SIN_CORREO','DESTINATARIO_NO_RESOLUBLE','NO_RECIPIENTS','COMPOSICION_INCOMPLETA')
)

ALTER TABLE aviso_correo ADD CONSTRAINT ck_aviso_correo_enviado CHECK (
    status <> 'ENVIADO' OR (message_id IS NOT NULL AND sent_at IS NOT NULL)
)

ALTER TABLE aviso_correo ADD CONSTRAINT ck_aviso_correo_locked CHECK (
    status = 'ENVIANDO' OR locked_by IS NULL
)

DECLARE
    v_usuario  NUMBER;
    v_aviso_1  VARCHAR2(36 CHAR);
    v_aviso_2  VARCHAR2(36 CHAR);
    v_status   VARCHAR2(20 CHAR);
    v_intentos NUMBER;
    v_tope     NUMBER;
    v_filas    NUMBER;
    v_sqlcode  NUMBER := 0;

    c_clave  CONSTANT VARCHAR2(120 CHAR) := 'ORACULO-TSK057|STATUS_CHANGE_ALERT|42|7';
    c_nombre CONSTANT VARCHAR2(150 CHAR) := 'Oraculo TSK-057 Reportante';
    c_correo CONSTANT VARCHAR2(254 CHAR) := 'oraculo.tsk057.idem@example.invalid';
    c_asunto CONSTANT VARCHAR2(255 CHAR) := 'Credencial emitida (oraculo TSK-057)';
    c_cuerpo CONSTANT VARCHAR2(200 CHAR) := 'Cuerpo congelado del oraculo TSK-057.';

    -- Semilla idempotente del catalogo de clave fija que necesita el escenario. El display_order
    -- queda fuera del rango de las semillas reales para que no se confunda con ellas.
    PROCEDURE sembrar_rol(p_code VARCHAR2, p_name VARCHAR2, p_order NUMBER) IS
    BEGIN
        MERGE INTO cat_rol d
        USING (SELECT p_code AS role_code FROM dual) s
           ON (d.role_code = s.role_code)
        WHEN NOT MATCHED THEN
            INSERT (role_code, role_name, display_order, is_active)
            VALUES (p_code, p_name, p_order, 'Y');
    END sembrar_rol;
BEGIN
    sembrar_rol('EMPLEADO', 'Empleado', 971);

    -- username, password_hash y password_algorithm son NOT NULL sin default desde
    -- 06-usuario-credenciales.xml, y ux_usuario_username_ci exige un username distinto por cuenta.
    INSERT INTO usuario (full_name, corporate_email, username, role_code, status,
                         password_hash, password_algorithm)
         VALUES (c_nombre, c_correo, 'oraculo.tsk057.idem', 'EMPLEADO', 'ACTIVO',
                 'hash-oraculo-tsk057-idem', 'argon2id')
      RETURNING user_id INTO v_usuario;

    -- El identificador del aviso lo genera el emisor (VARCHAR2(36)): SYS_GUID en hexadecimal
    -- minuscula ocupa 32 caracteres y cabe de sobra. SYS_GUID es funcion de SQL y se invoca
    -- con un SELECT ... FROM dual, igual que STANDARD_HASH en el oraculo de TSK-056.
    SELECT LOWER(RAWTOHEX(SYS_GUID())) INTO v_aviso_1 FROM dual;

    -- Primer encolado. status se deja SIN INFORMAR a proposito: lo que se verifica despues es
    -- precisamente el DEFAULT de la columna, no un valor escrito por el cliente.
    INSERT INTO aviso_correo (notification_id, notification_key, notification_type,
                              recipient_user_id, recipient_email, subject, body_text)
         VALUES (v_aviso_1, c_clave, 'CREDENTIAL_ISSUED',
                 v_usuario, c_correo, c_asunto, c_cuerpo);

    -- ---------------------------------------------------------------------------------
    -- Comprobacion 1 (AC-AVI-01): la solicitud nace PENDIENTE, con 0 intentos y tope 3,
    -- y se lee DE LA TABLA, no de las variables del escenario
    -- ---------------------------------------------------------------------------------
    SELECT status, attempt_count, max_attempts
      INTO v_status, v_intentos, v_tope
      FROM aviso_correo
     WHERE notification_id = v_aviso_1;

    IF v_status <> 'PENDIENTE' THEN
        RAISE_APPLICATION_ERROR(-20990, 'ORACULO TSK-057 / AC-AVI-01: el aviso recien encolado deberia nacer en estado PENDIENTE sin que la aplicacion lo informe, y ha nacido en ' || v_status);
    END IF;

    IF v_intentos <> 0 OR v_tope <> 3 THEN
        RAISE_APPLICATION_ERROR(-20990, 'ORACULO TSK-057 / AC-AVI-01: el aviso recien encolado deberia nacer con attempt_count 0 y max_attempts 3, y tiene attempt_count ' || v_intentos || ' y max_attempts ' || v_tope);
    END IF;

    -- -------------------------------------------------------------------------------------
    -- Comprobacion 2 (AC-AVI-02): el reintento con la MISMA notification_key es rechazado.
    -- El notification_id es nuevo y distinto, de modo que lo unico que colisiona es la clave
    -- de negocio. El bloque anidado captura la violacion para poder examinar su SQLCODE.
    -- -------------------------------------------------------------------------------------
    SELECT LOWER(RAWTOHEX(SYS_GUID())) INTO v_aviso_2 FROM dual;

    BEGIN
        INSERT INTO aviso_correo (notification_id, notification_key, notification_type,
                                  recipient_user_id, recipient_email, subject, body_text)
             VALUES (v_aviso_2, c_clave, 'CREDENTIAL_ISSUED',
                     v_usuario, c_correo, c_asunto, c_cuerpo);
    EXCEPTION
        WHEN DUP_VAL_ON_INDEX THEN
            v_sqlcode := SQLCODE;
    END;

    IF v_sqlcode <> -1 THEN
        RAISE_APPLICATION_ERROR(-20991, 'ORACULO TSK-057: el segundo INSERT con la misma notification_key NO fue rechazado con ORA-00001 (SQLCODE=' || v_sqlcode || '): la idempotencia del reintento no esta garantizada');
    END IF;

    -- El despachador tiene que seguir teniendo EXACTAMENTE un aviso que entregar.
    SELECT COUNT(*) INTO v_filas FROM aviso_correo WHERE notification_key = c_clave;
    IF v_filas <> 1 THEN
        RAISE_APPLICATION_ERROR(-20991, 'ORACULO TSK-057 / AC-AVI-02: tras el reintento deberia quedar exactamente 1 aviso con esa notification_key y hay ' || v_filas);
    END IF;

    ROLLBACK;
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        RAISE;
END;

DECLARE
    v_usuario  NUMBER;
    v_aviso    VARCHAR2(36 CHAR);
    v_status   VARCHAR2(20 CHAR);
    v_error    VARCHAR2(50 CHAR);
    v_message  VARCHAR2(255 CHAR);
    v_filas    NUMBER := 0;
    v_sqlcode  NUMBER := 0;

    c_clave   CONSTANT VARCHAR2(120 CHAR) := 'ORACULO-TSK057|TERMINAL|1';
    c_nombre  CONSTANT VARCHAR2(150 CHAR) := 'Oraculo TSK-057 Entregado';
    c_correo  CONSTANT VARCHAR2(254 CHAR) := 'oraculo.tsk057.terminal@example.invalid';
    c_asunto  CONSTANT VARCHAR2(255 CHAR) := 'Credencial emitida (oraculo TSK-057)';
    c_cuerpo  CONSTANT VARCHAR2(200 CHAR) := 'Cuerpo congelado del oraculo TSK-057.';
    c_message CONSTANT VARCHAR2(255 CHAR) := '<oraculo-tsk057@mapfre.invalid>';

    PROCEDURE sembrar_rol(p_code VARCHAR2, p_name VARCHAR2, p_order NUMBER) IS
    BEGIN
        MERGE INTO cat_rol d
        USING (SELECT p_code AS role_code FROM dual) s
           ON (d.role_code = s.role_code)
        WHEN NOT MATCHED THEN
            INSERT (role_code, role_name, display_order, is_active)
            VALUES (p_code, p_name, p_order, 'Y');
    END sembrar_rol;

    -- Mismo patron para las tres salidas prohibidas: bloque anidado que intenta la transicion,
    -- captura el SQLCODE y exige que sea exactamente -20060. Se comprueba el codigo numerico para
    -- que el oraculo no se conforme con "fallo algo". El UPDATE arrastra ademas un last_error_code,
    -- que es lo que despues permite comprobar que el rechazo no dejo rastro en la fila.
    PROCEDURE exigir_rechazo(p_destino VARCHAR2) IS
    BEGIN
        v_sqlcode := 0;
        BEGIN
            UPDATE aviso_correo
               SET status          = p_destino,
                   last_error_code = 'TRANSIENT_ERROR'
             WHERE notification_id = v_aviso;
        EXCEPTION
            WHEN OTHERS THEN
                v_sqlcode := SQLCODE;
        END;

        IF v_sqlcode <> -20060 THEN
            RAISE_APPLICATION_ERROR(-20992, 'ORACULO TSK-057: el UPDATE de ENVIADO a ' || p_destino || ' NO fue rechazado con ORA-20060 (SQLCODE=' || v_sqlcode || '): el estado ENVIADO no es terminal');
        END IF;
    END exigir_rechazo;
BEGIN
    sembrar_rol('EMPLEADO', 'Empleado', 972);

    INSERT INTO usuario (full_name, corporate_email, username, role_code, status,
                         password_hash, password_algorithm)
         VALUES (c_nombre, c_correo, 'oraculo.tsk057.terminal', 'EMPLEADO', 'ACTIVO',
                 'hash-oraculo-tsk057-terminal', 'argon2id')
      RETURNING user_id INTO v_usuario;

    SELECT LOWER(RAWTOHEX(SYS_GUID())) INTO v_aviso FROM dual;

    -- Aviso YA ENTREGADO. ck_aviso_correo_enviado exige message_id y sent_at en ENVIADO, de modo
    -- que el escenario no puede montarse sin ellos.
    INSERT INTO aviso_correo (notification_id, notification_key, notification_type,
                              recipient_user_id, recipient_email, subject, body_text,
                              status, attempt_count, message_id, sent_at)
         VALUES (v_aviso, c_clave, 'CREDENTIAL_ISSUED',
                 v_usuario, c_correo, c_asunto, c_cuerpo,
                 'ENVIADO', 1, c_message, SYS_EXTRACT_UTC(SYSTIMESTAMP));

    -- -------------------------------------------------------------------------------------
    -- Comprobacion 1 (REQ-142 regla 2 / AC-SMTP-02): ninguna salida de ENVIADO esta permitida,
    -- ni a los estados de fallo ni de vuelta a la cola (AC-AVI-06 / AC-SMTP-09)
    -- -------------------------------------------------------------------------------------
    exigir_rechazo('FALLIDO');
    exigir_rechazo('DESCARTADO');
    exigir_rechazo('PENDIENTE');

    -- -------------------------------------------------------------------------------
    -- Comprobacion 2: el rechazo es atomico y la fila entregada quedo intacta
    -- -------------------------------------------------------------------------------
    SELECT status, last_error_code, message_id
      INTO v_status, v_error, v_message
      FROM aviso_correo
     WHERE notification_id = v_aviso;

    IF v_status <> 'ENVIADO' OR v_error IS NOT NULL OR v_message <> c_message THEN
        RAISE_APPLICATION_ERROR(-20993, 'ORACULO TSK-057: el aviso ENVIADO quedo alterado tras el UPDATE rechazado');
    END IF;

    -- ------------------------------------------------------------------------------------
    -- Comprobacion 3: el trigger no es un candado global. El UPDATE que NO cambia de estado
    -- (el que registra el reenvio sobre una fila ya entregada) tiene que pasar.
    -- ------------------------------------------------------------------------------------
    BEGIN
        UPDATE aviso_correo
           SET resent_at = SYS_EXTRACT_UTC(SYSTIMESTAMP)
         WHERE notification_id = v_aviso;
        v_filas := SQL%ROWCOUNT;
    EXCEPTION
        WHEN OTHERS THEN
            v_filas := -1;
    END;

    IF v_filas <> 1 THEN
        RAISE_APPLICATION_ERROR(-20993, 'ORACULO TSK-057: el trigger de estado terminal bloquea un UPDATE que no cambia de estado');
    END IF;

    ROLLBACK;
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        RAISE;
END;

DECLARE
    v_admin          NUMBER;
    v_empleado       NUMBER;
    v_tecnico        NUMBER;
    v_oficina        NUMBER;
    v_sala           NUMBER;
    v_categoria      NUMBER;
    v_inc            NUMBER;
    v_hist           NUMBER;
    v_now            TIMESTAMP := SYS_EXTRACT_UTC(SYSTIMESTAMP);
    v_t0             TIMESTAMP;
    v_t1             TIMESTAMP;
    v_hash_alta      VARCHAR2(64 CHAR);
    v_hash_cambio    VARCHAR2(64 CHAR);
    v_aviso_alta     VARCHAR2(36 CHAR);
    v_aviso_alta_bis VARCHAR2(36 CHAR);
    v_aviso_cambio   VARCHAR2(36 CHAR);
    v_aviso_cam_bis  VARCHAR2(36 CHAR);
    v_status         VARCHAR2(20 CHAR);
    v_filas          NUMBER;
    v_avisos         NUMBER;
    v_incidencias    NUMBER;
    v_claves         NUMBER;
    v_sqlcode        NUMBER := 0;

    c_prefijo       CONSTANT VARCHAR2(20 CHAR)  := 'ORACULO-TSK057|';
    c_admin_nom     CONSTANT VARCHAR2(120 CHAR) := 'Oraculo TSK-057 Outbox Administrador';
    c_empleado_nom  CONSTANT VARCHAR2(120 CHAR) := 'Oraculo TSK-057 Outbox Reportante';
    c_tecnico_nom   CONSTANT VARCHAR2(120 CHAR) := 'Oraculo TSK-057 Outbox Tecnico';
    c_empleado_mail CONSTANT VARCHAR2(150 CHAR) := 'oraculo.tsk057.outbox.reportante@example.invalid';
    c_referencia    CONSTANT VARCHAR2(30 CHAR)  := 'INC-ORA57-000001';
    c_descripcion   CONSTANT VARCHAR2(500 CHAR) := 'El climatizador de la sala de reuniones no enfria y la sala se queda inutilizable toda la manana';
    c_sala_nom      CONSTANT VARCHAR2(80 CHAR)  := 'Sala del oraculo TSK-057';
    c_oficina_nom   CONSTANT VARCHAR2(80 CHAR)  := 'Oficina del oraculo TSK-057';
    c_categoria_nm  CONSTANT VARCHAR2(60 CHAR)  := 'Climatizacion oraculo TSK-057';
    c_alta_nota     CONSTANT VARCHAR2(500 CHAR) := 'Alta de la incidencia desde el oraculo de outbox TSK-057';
    c_cambio_nota   CONSTANT VARCHAR2(500 CHAR) := 'Cambio de estado desde el oraculo de outbox TSK-057';
    c_asunto_alta   CONSTANT VARCHAR2(255 CHAR) := 'Nueva incidencia registrada (oraculo TSK-057)';
    c_cuerpo_alta   CONSTANT VARCHAR2(500 CHAR) := 'Cuerpo congelado del aviso de alta del oraculo TSK-057.';
    c_asunto_cam    CONSTANT VARCHAR2(255 CHAR) := 'Cambio de estado de su incidencia (oraculo TSK-057)';
    c_cuerpo_cam    CONSTANT VARCHAR2(500 CHAR) := 'Cuerpo congelado del aviso de cambio de estado del oraculo TSK-057.';

    -- Semillas idempotentes de los catalogos de clave fija. Los display_order quedan fuera del
    -- rango de las semillas reales y fuera del de los oraculos anteriores (971 y 972), porque
    -- uk_cat_rol_display_order y uk_cat_categoria_display_order son UNIQUE.
    PROCEDURE sembrar_rol(p_code VARCHAR2, p_name VARCHAR2, p_order NUMBER) IS
    BEGIN
        MERGE INTO cat_rol d
        USING (SELECT p_code AS role_code FROM dual) s
           ON (d.role_code = s.role_code)
        WHEN NOT MATCHED THEN
            INSERT (role_code, role_name, display_order, is_active)
            VALUES (p_code, p_name, p_order, 'Y');
    END sembrar_rol;

    PROCEDURE sembrar_estado(p_code VARCHAR2, p_name VARCHAR2, p_order NUMBER, p_terminal VARCHAR2) IS
    BEGIN
        MERGE INTO cat_estado_incidencia d
        USING (SELECT p_code AS status_code FROM dual) s
           ON (d.status_code = s.status_code)
        WHEN NOT MATCHED THEN
            INSERT (status_code, status_name, sort_order, is_terminal, is_active)
            VALUES (p_code, p_name, p_order, p_terminal, 'Y');
    END sembrar_estado;

    -- Los catalogos de clave IDENTITY no admiten MERGE con RETURNING, de modo que se resuelven
    -- con el equivalente "buscar o insertar": si la semilla real ya existe se reutiliza, y si no
    -- se crea una propia del oraculo que el ROLLBACK final se lleva por delante.
    FUNCTION oficina_oraculo RETURN NUMBER IS
        l_id NUMBER;
    BEGIN
        SELECT office_id INTO l_id FROM cat_oficina WHERE office_code = 'ORA57';
        -- Si la oficina YA existia se REACTIVA antes de devolverla: trg_cat_sala_oficina_activa
        -- rechaza colgar una sala de una oficina inactiva. Es un UPDATE de DATOS (no DDL) que vive
        -- dentro de la transaccion del oraculo y que el ROLLBACK final revierte.
        UPDATE cat_oficina SET is_active = 'Y' WHERE office_id = l_id AND is_active <> 'Y';
        RETURN l_id;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            INSERT INTO cat_oficina (office_code, office_name, city, is_active)
                 VALUES ('ORA57', c_oficina_nom, 'Madrid', 'Y')
              RETURNING office_id INTO l_id;
            RETURN l_id;
    END oficina_oraculo;

    FUNCTION sala_oraculo(p_office_id NUMBER, p_created_by NUMBER) RETURN NUMBER IS
        l_id NUMBER;
    BEGIN
        SELECT room_id INTO l_id FROM cat_sala WHERE room_code = 'ORA57-SALA-01';
        -- Si la sala YA existia se REACTIVA antes de devolverla: trg_incidencia_clasificacion
        -- rechaza con ORA-20011 el alta sobre una sala inactiva.
        UPDATE cat_sala SET is_active = 'Y' WHERE room_id = l_id AND is_active <> 'Y';
        RETURN l_id;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            INSERT INTO cat_sala (room_code, room_name, office_id, is_active, created_by)
                 VALUES ('ORA57-SALA-01', c_sala_nom, p_office_id, 'Y', p_created_by)
              RETURNING room_id INTO l_id;
            RETURN l_id;
    END sala_oraculo;

    FUNCTION categoria_oraculo RETURN NUMBER IS
        l_id NUMBER;
    BEGIN
        SELECT category_id INTO l_id FROM cat_categoria_incidencia WHERE category_code = 'CLIMATIZACION';
        -- El oraculo NO puede usar un category_code propio porque ck_cat_categoria_code cierra el
        -- enumerado, de modo que reutiliza CLIMATIZACION. Si la fila YA existia se REACTIVA antes de
        -- devolverla: trg_incidencia_clasificacion rechaza con ORA-20012 el alta sobre una categoria
        -- inactiva. Mismo criterio que en oficina_oraculo: UPDATE de DATOS que el ROLLBACK deshace.
        UPDATE cat_categoria_incidencia SET is_active = 'Y' WHERE category_id = l_id AND is_active <> 'Y';
        RETURN l_id;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            INSERT INTO cat_categoria_incidencia (category_code, category_name, display_order, is_active)
                 VALUES ('CLIMATIZACION', c_categoria_nm, 976, 'Y')
              RETURNING category_id INTO l_id;
            RETURN l_id;
    END categoria_oraculo;

    -- Huella SIMPLIFICADA: este oraculo verifica el OUTBOX, no la cadena de huellas de TSK-056, de
    -- modo que no reproduce la forma canonica del asiento. STANDARD_HASH es funcion de SQL y se
    -- invoca con SELECT ... FROM dual; RAWTOHEX devuelve hexadecimal en MAYUSCULAS, que es
    -- exactamente lo que admite ck_inc_hist_entry_hash ('^[0-9A-F]{64}$').
    FUNCTION huella(p_semilla VARCHAR2) RETURN VARCHAR2 IS
        l_hash VARCHAR2(64 CHAR);
    BEGIN
        SELECT RAWTOHEX(STANDARD_HASH('oraculo-tsk057-' || p_semilla, 'SHA256')) INTO l_hash FROM dual;
        RETURN l_hash;
    END huella;
BEGIN
    v_t0 := v_now - INTERVAL '4' HOUR;
    v_t1 := v_now - INTERVAL '3' HOUR;

    -- ==================================================================================
    -- MONTAJE: catalogos, cuentas y clasificacion del escenario
    -- ==================================================================================
    sembrar_rol('EMPLEADO',              'Empleado',               973);
    sembrar_rol('TECNICO_MANTENIMIENTO', 'Tecnico de mantenimiento', 974);
    sembrar_rol('ADMINISTRADOR',         'Administrador',          975);

    sembrar_estado('ABIERTA',  'Abierta',  1, 'N');
    sembrar_estado('EN_CURSO', 'En curso', 2, 'N');
    sembrar_estado('RESUELTA', 'Resuelta', 3, 'N');
    sembrar_estado('CERRADA',  'Cerrada',  4, 'Y');

    -- username, password_hash y password_algorithm son NOT NULL sin default desde
    -- 06-usuario-credenciales.xml, y ux_usuario_username_ci exige un username distinto por cuenta.
    INSERT INTO usuario (full_name, corporate_email, username, role_code, status,
                         password_hash, password_algorithm)
         VALUES (c_admin_nom, 'oraculo.tsk057.outbox.admin@example.invalid',
                 'oraculo.tsk057.outbox.admin', 'ADMINISTRADOR', 'ACTIVO',
                 'hash-oraculo-tsk057-outbox-admin', 'argon2id')
      RETURNING user_id INTO v_admin;

    INSERT INTO usuario (full_name, corporate_email, username, role_code, status,
                         password_hash, password_algorithm, created_at, created_by)
         VALUES (c_empleado_nom, c_empleado_mail,
                 'oraculo.tsk057.outbox.reportante', 'EMPLEADO', 'ACTIVO',
                 'hash-oraculo-tsk057-outbox-reportante', 'argon2id', v_t0, v_admin)
      RETURNING user_id INTO v_empleado;

    INSERT INTO usuario (full_name, corporate_email, username, role_code, status,
                         password_hash, password_algorithm, created_at, created_by)
         VALUES (c_tecnico_nom, 'oraculo.tsk057.outbox.tecnico@example.invalid',
                 'oraculo.tsk057.outbox.tecnico', 'TECNICO_MANTENIMIENTO', 'ACTIVO',
                 'hash-oraculo-tsk057-outbox-tecnico', 'argon2id', v_t0, v_admin)
      RETURNING user_id INTO v_tecnico;

    v_oficina   := oficina_oraculo;
    v_sala      := sala_oraculo(v_oficina, v_admin);
    v_categoria := categoria_oraculo;

    -- ==================================================================================
    -- LA UNIDAD DE TRABAJO DEL ALTA: incidencia y solicitud de aviso en la MISMA
    -- transaccion, que es literalmente lo que significa el patron outbox de ADR-006
    -- ==================================================================================
    INSERT INTO incidencia (reference_code, room_id, category_id,
                            room_name_snapshot, office_name_snapshot, category_name_snapshot,
                            description, status, reported_by, created_at,
                            status_changed_at, status_changed_by)
         VALUES (c_referencia, v_sala, v_categoria,
                 c_sala_nom, c_oficina_nom, c_categoria_nm,
                 c_descripcion,
                 'ABIERTA', v_empleado, v_t0, v_t0, NULL)
      RETURNING incident_id INTO v_inc;

    -- El identificador del aviso lo genera el emisor (VARCHAR2(36)): SYS_GUID en hexadecimal
    -- minuscula ocupa 32 caracteres y cabe de sobra.
    SELECT LOWER(RAWTOHEX(SYS_GUID())) INTO v_aviso_alta FROM dual;

    -- Encolado del aviso de alta, SIN COMMIT por medio. recipient_user_id y recipient_email van
    -- NULOS A PROPOSITO: el aviso de alta se dirige al COLECTIVO de tecnicos de mantenimiento y sus
    -- destinatarios se resuelven contra el directorio en el momento del despacho (REQ-082 /
    -- REQ-131). Que este INSERT pase es ya una comprobacion: una NOT NULL sobre el destinatario
    -- romperia el encolado dentro de la transaccion del alta. status se deja SIN INFORMAR para que
    -- lo ponga el DEFAULT de la columna.
    INSERT INTO aviso_correo (notification_id, notification_key, notification_type,
                              incident_id, history_entry_id,
                              recipient_user_id, recipient_email, subject, body_text)
         VALUES (v_aviso_alta, c_prefijo || 'NEW_INCIDENT_ALERT|' || v_inc, 'NEW_INCIDENT_ALERT',
                 v_inc, NULL,
                 NULL, NULL, c_asunto_alta, c_cuerpo_alta);

    -- -------------------------------------------------------------------------------------
    -- Comprobacion 1 (AC-AVI-01): el alta deja EXACTAMENTE una solicitud de aviso de alta y
    -- nace PENDIENTE. Se lee DE LA TABLA, no de las variables del escenario. El COUNT va por
    -- separado del estado (con MAX) para que un recuento distinto de 1 no reviente con
    -- NO_DATA_FOUND o TOO_MANY_ROWS antes de poder contarlo en el mensaje de error.
    -- -------------------------------------------------------------------------------------
    SELECT COUNT(*) INTO v_filas
      FROM aviso_correo
     WHERE incident_id = v_inc AND notification_type = 'NEW_INCIDENT_ALERT';

    SELECT MAX(status) INTO v_status
      FROM aviso_correo
     WHERE incident_id = v_inc AND notification_type = 'NEW_INCIDENT_ALERT';

    IF v_filas <> 1 OR NVL(v_status, '~') <> 'PENDIENTE' THEN
        RAISE_APPLICATION_ERROR(-20994, 'ORACULO TSK-057 / AC-AVI-01: el alta deberia dejar exactamente una solicitud NEW_INCIDENT_ALERT en PENDIENTE para la incidencia, y hay ' || v_filas || ' en estado ' || NVL(v_status, '(ninguno)'));
    END IF;

    -- -------------------------------------------------------------------------------------
    -- Comprobacion 2 (AC-AVI-02): ningun SEGUNDO aviso de alta para la misma incidencia.
    -- La notification_key es DISTINTA a proposito: asi lo que rechaza este INSERT es el indice
    -- unico parcial ux_aviso_correo_alta y NO uk_aviso_correo_notif_key (que ya verifica el
    -- oraculo 14-05). Si se reutilizase la clave de negocio, el indice parcial podria estar mal
    -- definido o no existir y la comprobacion pasaria igualmente, sin demostrar nada.
    -- -------------------------------------------------------------------------------------
    SELECT LOWER(RAWTOHEX(SYS_GUID())) INTO v_aviso_alta_bis FROM dual;

    v_sqlcode := 0;
    BEGIN
        INSERT INTO aviso_correo (notification_id, notification_key, notification_type,
                                  incident_id, history_entry_id,
                                  recipient_user_id, recipient_email, subject, body_text)
             VALUES (v_aviso_alta_bis, c_prefijo || 'NEW_INCIDENT_ALERT|BIS|' || v_inc, 'NEW_INCIDENT_ALERT',
                     v_inc, NULL,
                     NULL, NULL, c_asunto_alta, c_cuerpo_alta);
    EXCEPTION
        WHEN DUP_VAL_ON_INDEX THEN
            v_sqlcode := SQLCODE;
    END;

    IF v_sqlcode <> -1 THEN
        RAISE_APPLICATION_ERROR(-20994, 'ORACULO TSK-057 / AC-AVI-02: el segundo aviso de alta para la misma incidencia NO fue rechazado con ORA-00001 (SQLCODE=' || v_sqlcode || '): el equipo de mantenimiento recibiria un segundo correo de alta');
    END IF;

    -- -------------------------------------------------------------------------------------
    -- Comprobacion 3 (REQ-137): el indice parcial NO es un candado por incidencia. Se escriben
    -- los dos asientos de historico del escenario (el de alta y un cambio de estado) y se encola
    -- el aviso de cambio de estado de la MISMA incidencia, que TIENE que pasar. Sin esta
    -- comprobacion, un indice unico sobre incident_id a secas pasaria las comprobaciones 1, 2 y 4
    -- y dejaria el sistema sin ningun aviso de cambio de estado.
    -- -------------------------------------------------------------------------------------
    v_hash_alta := huella('creacion|' || v_inc);

    INSERT INTO incidencia_historico (
        incident_id, entry_type, from_status, to_status,
        actor_user_id, actor_display_name, changed_at,
        entry_comment, previous_entry_hash, entry_hash)
    VALUES (
        v_inc, 'CREACION', NULL, 'ABIERTA',
        v_empleado, c_empleado_nom, v_t0,
        c_alta_nota, NULL, v_hash_alta);

    v_hash_cambio := huella('cambio|' || v_inc || '|' || v_hash_alta);

    INSERT INTO incidencia_historico (
        incident_id, entry_type, from_status, to_status,
        actor_user_id, actor_display_name, changed_at,
        entry_comment, previous_entry_hash, entry_hash)
    VALUES (
        v_inc, 'CAMBIO_ESTADO', 'ABIERTA', 'EN_CURSO',
        v_tecnico, c_tecnico_nom, v_t1,
        c_cambio_nota, v_hash_alta, v_hash_cambio)
    RETURNING history_id INTO v_hist;

    SELECT LOWER(RAWTOHEX(SYS_GUID())) INTO v_aviso_cambio FROM dual;

    v_sqlcode := 0;
    BEGIN
        INSERT INTO aviso_correo (notification_id, notification_key, notification_type,
                                  incident_id, history_entry_id,
                                  recipient_user_id, recipient_email, subject, body_text,
                                  previous_status_code, new_status_code)
             VALUES (v_aviso_cambio, c_prefijo || 'STATUS_CHANGE_ALERT|' || v_inc || '|' || v_hist, 'STATUS_CHANGE_ALERT',
                     v_inc, v_hist,
                     v_empleado, c_empleado_mail, c_asunto_cam, c_cuerpo_cam,
                     'ABIERTA', 'EN_CURSO');
    EXCEPTION
        WHEN OTHERS THEN
            v_sqlcode := SQLCODE;
    END;

    IF v_sqlcode <> 0 THEN
        RAISE_APPLICATION_ERROR(-20995, 'ORACULO TSK-057 / REQ-137: el aviso de cambio de estado de la misma incidencia fue rechazado (SQLCODE=' || v_sqlcode || '): el indice de unicidad del aviso de alta es demasiado amplio');
    END IF;

    -- -------------------------------------------------------------------------------------
    -- Comprobacion 4 (REQ-137): un unico aviso por ENTRADA de historico. Igual que en la
    -- comprobacion 2, la notification_key es DISTINTA para que el unico mecanismo capaz de
    -- rechazar el INSERT sea el indice unico parcial ux_aviso_correo_cambio_estado.
    -- -------------------------------------------------------------------------------------
    SELECT LOWER(RAWTOHEX(SYS_GUID())) INTO v_aviso_cam_bis FROM dual;

    v_sqlcode := 0;
    BEGIN
        INSERT INTO aviso_correo (notification_id, notification_key, notification_type,
                                  incident_id, history_entry_id,
                                  recipient_user_id, recipient_email, subject, body_text,
                                  previous_status_code, new_status_code)
             VALUES (v_aviso_cam_bis, c_prefijo || 'STATUS_CHANGE_ALERT|BIS|' || v_inc || '|' || v_hist, 'STATUS_CHANGE_ALERT',
                     v_inc, v_hist,
                     v_empleado, c_empleado_mail, c_asunto_cam, c_cuerpo_cam,
                     'ABIERTA', 'EN_CURSO');
    EXCEPTION
        WHEN DUP_VAL_ON_INDEX THEN
            v_sqlcode := SQLCODE;
    END;

    IF v_sqlcode <> -1 THEN
        RAISE_APPLICATION_ERROR(-20995, 'ORACULO TSK-057 / REQ-137: una segunda solicitud para la misma entrada de historico NO fue rechazada con ORA-00001: el reportante recibiria dos correos del mismo cambio de estado');
    END IF;

    -- -------------------------------------------------------------------------------------
    -- Comprobacion 5 (AC-AVI-05, patron outbox): el ROLLBACK del alta que fracasa se lleva por
    -- delante TAMBIEN la solicitud de aviso, porque vive dentro de la misma transaccion. Si
    -- quedase una sola fila, el despachador acabaria entregando un correo por una incidencia que
    -- nunca existio. Los recuentos se leen DESPUES del ROLLBACK.
    -- -------------------------------------------------------------------------------------
    ROLLBACK;

    SELECT COUNT(*) INTO v_avisos      FROM aviso_correo WHERE incident_id = v_inc;
    SELECT COUNT(*) INTO v_incidencias FROM incidencia   WHERE incident_id = v_inc;

    IF v_avisos <> 0 OR v_incidencias <> 0 THEN
        RAISE_APPLICATION_ERROR(-20996, 'ORACULO TSK-057 / AC-AVI-05: tras revertir el alta quedan ' || v_avisos || ' filas en aviso_correo y ' || v_incidencias || ' en incidencia: la solicitud de aviso no vive dentro de la transaccion del alta');
    END IF;

    -- Ninguna clave del oraculo puede sobrevivir. El patron no necesita ESCAPE: el separador es
    -- la barra vertical y no el guion bajo, de modo que no hay comodin de un solo caracter.
    SELECT COUNT(*) INTO v_claves
      FROM aviso_correo
     WHERE notification_key LIKE 'ORACULO-TSK057|%';

    IF v_claves <> 0 THEN
        RAISE_APPLICATION_ERROR(-20996, 'ORACULO TSK-057 / AC-AVI-05: tras revertir el alta quedan ' || v_claves || ' solicitudes del oraculo en el outbox: la solicitud de aviso no vive dentro de la transaccion del alta');
    END IF;

    ROLLBACK;
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        RAISE;
END;

DECLARE
    v_usuario     NUMBER;
    v_aviso_a     VARCHAR2(36 CHAR);
    v_aviso_b     VARCHAR2(36 CHAR);
    v_tomada_1    VARCHAR2(36 CHAR);
    v_tomada_2    VARCHAR2(36 CHAR);
    v_tomada_3    VARCHAR2(36 CHAR);
    v_vacio       BOOLEAN;
    v_rol_creado  BOOLEAN := FALSE;
    v_n           NUMBER;

    c_prefijo  CONSTANT VARCHAR2(30 CHAR)  := 'ORACULO-TSK057|FIFO|';
    c_username CONSTANT VARCHAR2(100 CHAR) := 'oraculo.tsk057.fifo';
    c_nombre   CONSTANT VARCHAR2(150 CHAR) := 'Oraculo TSK-057 Concurrencia';
    c_correo   CONSTANT VARCHAR2(254 CHAR) := 'oraculo.tsk057.fifo@example.invalid';
    c_asunto   CONSTANT VARCHAR2(255 CHAR) := 'Credencial emitida (oraculo TSK-057)';
    c_cuerpo   CONSTANT VARCHAR2(200 CHAR) := 'Cuerpo congelado del oraculo TSK-057.';

    -- La cola del PRIMER despachador, en la transaccion principal. Cursor EXPLICITO porque Oracle
    -- no admite FETCH FIRST ... ROWS ONLY junto a FOR UPDATE: se ordena y se toma una sola fila.
    CURSOR c_cola IS
        SELECT notification_id
          FROM aviso_correo
         WHERE status = 'PENDIENTE'
           AND notification_key LIKE c_prefijo || '%'
         ORDER BY created_at, notification_key
           FOR UPDATE SKIP LOCKED;

    PROCEDURE sembrar_rol(p_code VARCHAR2, p_name VARCHAR2, p_order NUMBER) IS
    BEGIN
        MERGE INTO cat_rol d
        USING (SELECT p_code AS role_code FROM dual) s
           ON (d.role_code = s.role_code)
        WHEN NOT MATCHED THEN
            INSERT (role_code, role_name, display_order, is_active)
            VALUES (p_code, p_name, p_order, 'Y');
    END sembrar_rol;

    -- Este oraculo CONFIRMA su escenario, de modo que un ROLLBACK ya no basta para dejar la base
    -- como estaba: lo escrito se borra explicitamente. El rol solo se borra si lo creo el propio
    -- oraculo, para no llevarse por delante una semilla preexistente.
    PROCEDURE limpiar IS
    BEGIN
        DELETE FROM aviso_correo WHERE notification_key LIKE c_prefijo || '%';
        DELETE FROM usuario WHERE username = c_username;
        IF v_rol_creado THEN
            DELETE FROM cat_rol WHERE role_code = 'EMPLEADO';
        END IF;
        COMMIT;
    END limpiar;

    -- SEGUNDA CONEXION: el otro despachador. La transaccion autonoma es independiente de la
    -- principal (no ve sus cambios sin confirmar ni comparte sus bloqueos), que es justo lo que
    -- hace de ella un worker concurrente creible. Devuelve el notification_id tomado, o NULL si
    -- SKIP LOCKED no le dejo ninguna fila disponible. Cierra SIEMPRE su transaccion antes de
    -- salir, porque una transaccion autonoma que termina sin confirmar ni deshacer provoca
    -- ORA-06519.
    FUNCTION tomar_en_otra_transaccion(p_worker VARCHAR2) RETURN VARCHAR2 IS
        PRAGMA AUTONOMOUS_TRANSACTION;
        CURSOR c_otra IS
            SELECT notification_id
              FROM aviso_correo
             WHERE status = 'PENDIENTE'
               AND notification_key LIKE c_prefijo || '%'
             ORDER BY created_at, notification_key
               FOR UPDATE SKIP LOCKED;
        l_id    VARCHAR2(36 CHAR);
        l_vacio BOOLEAN;
    BEGIN
        OPEN c_otra;
        FETCH c_otra INTO l_id;
        l_vacio := c_otra%NOTFOUND;
        CLOSE c_otra;

        IF l_vacio THEN
            ROLLBACK;
            RETURN NULL;
        END IF;

        UPDATE aviso_correo
           SET status    = 'ENVIANDO',
               locked_by = p_worker,
               locked_at = SYS_EXTRACT_UTC(SYSTIMESTAMP)
         WHERE notification_id = l_id;

        COMMIT;
        RETURN l_id;
    EXCEPTION
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE;
    END tomar_en_otra_transaccion;
BEGIN
    -- El rol solo se marca para borrado si NO existia: la limpieza no debe tocar las semillas reales.
    SELECT COUNT(*) INTO v_n FROM cat_rol WHERE role_code = 'EMPLEADO';
    v_rol_creado := (v_n = 0);
    sembrar_rol('EMPLEADO', 'Empleado', 977);

    INSERT INTO usuario (full_name, corporate_email, username, role_code, status,
                         password_hash, password_algorithm)
         VALUES (c_nombre, c_correo, c_username, 'EMPLEADO', 'ACTIVO',
                 'hash-oraculo-tsk057-fifo', 'argon2id')
      RETURNING user_id INTO v_usuario;

    SELECT LOWER(RAWTOHEX(SYS_GUID())) INTO v_aviso_a FROM dual;
    SELECT LOWER(RAWTOHEX(SYS_GUID())) INTO v_aviso_b FROM dual;

    -- Dos solicitudes PENDIENTE (status SIN INFORMAR: lo pone el DEFAULT) con created_at EXPLICITO,
    -- de modo que A es inequivocamente la PRIMERA en orden FIFO.
    INSERT INTO aviso_correo (notification_id, notification_key, notification_type,
                              recipient_user_id, recipient_email, subject, body_text, created_at)
         VALUES (v_aviso_a, c_prefijo || 'A', 'CREDENTIAL_ISSUED',
                 v_usuario, c_correo, c_asunto, c_cuerpo,
                 SYS_EXTRACT_UTC(SYSTIMESTAMP) - INTERVAL '2' MINUTE);

    INSERT INTO aviso_correo (notification_id, notification_key, notification_type,
                              recipient_user_id, recipient_email, subject, body_text, created_at)
         VALUES (v_aviso_b, c_prefijo || 'B', 'CREDENTIAL_ISSUED',
                 v_usuario, c_correo, c_asunto, c_cuerpo,
                 SYS_EXTRACT_UTC(SYSTIMESTAMP) - INTERVAL '1' MINUTE);

    -- CONFIRMACION DELIBERADA: sin ella la transaccion autonoma de la comprobacion 2 no veria
    -- ninguna fila. Todo lo confirmado aqui se borra en `limpiar`, tanto en el camino feliz como
    -- en el manejador de excepciones.
    COMMIT;

    -- ---------------------------------------------------------------------------------------
    -- Comprobacion 1 (REQ-132): el primer despachador toma la solicitud MAS ANTIGUA (FIFO)
    -- ---------------------------------------------------------------------------------------
    OPEN c_cola;
    FETCH c_cola INTO v_tomada_1;
    v_vacio := c_cola%NOTFOUND;
    CLOSE c_cola;

    IF v_vacio OR v_tomada_1 <> v_aviso_a THEN
        RAISE_APPLICATION_ERROR(-20997, 'ORACULO TSK-057 / REQ-132: el primer despachador deberia tomar el aviso mas antiguo (orden FIFO por created_at) y ha tomado otro');
    END IF;

    -- La toma de REQ-132: ENVIANDO con el testigo del worker. NO se confirma, porque el bloqueo
    -- tiene que seguir VIVO durante la comprobacion 2.
    UPDATE aviso_correo
       SET status    = 'ENVIANDO',
           locked_by = 'oraculo-worker-1',
           locked_at = SYS_EXTRACT_UTC(SYSTIMESTAMP)
     WHERE notification_id = v_tomada_1;

    -- -----------------------------------------------------------------------------------------
    -- Comprobacion 2 (AC-SMTP-02): el segundo despachador, en OTRA transaccion, se salta la fila
    -- bloqueada y se lleva la SIGUIENTE, no la misma ni ninguna
    -- -----------------------------------------------------------------------------------------
    v_tomada_2 := tomar_en_otra_transaccion('oraculo-worker-2');

    IF v_tomada_2 IS NULL THEN
        RAISE_APPLICATION_ERROR(-20998, 'ORACULO TSK-057 / REQ-132: el segundo despachador no obtuvo ninguna solicitud: SKIP LOCKED deberia saltarse la fila bloqueada por el primero y entregarle la siguiente, no dejarlo en vacio');
    END IF;

    IF v_tomada_2 = v_tomada_1 OR v_tomada_2 <> v_aviso_b THEN
        RAISE_APPLICATION_ERROR(-20998, 'ORACULO TSK-057 / AC-SMTP-02: los dos despachadores concurrentes obtuvieron la MISMA solicitud: el aviso se entregaria dos veces');
    END IF;

    -- -------------------------------------------------------------------------------------
    -- Comprobacion 3 (AC-SMTP-02): tomadas las dos, la cola esta VACIA para un tercer worker
    -- -------------------------------------------------------------------------------------
    v_tomada_3 := tomar_en_otra_transaccion('oraculo-worker-3');

    IF v_tomada_3 IS NOT NULL THEN
        RAISE_APPLICATION_ERROR(-20999, 'ORACULO TSK-057 / AC-SMTP-02: un tercer despachador obtuvo la solicitud ' || v_tomada_3 || ', ya tomada por otro: la cola entrega la misma fila dos veces');
    END IF;

    -- ------------------------------------------------------------------------------------------
    -- Comprobacion 4 (AC-AVI-06): el ROLLBACK simula la caida del primer worker. Suelta su bloqueo
    -- y revierte su toma, de modo que la solicitud vuelve a estar disponible sin generar correo.
    -- A continuacion se borra TODO lo que este oraculo confirmo.
    -- ------------------------------------------------------------------------------------------
    ROLLBACK;

    limpiar;

    SELECT COUNT(*) INTO v_n
      FROM aviso_correo
     WHERE notification_key LIKE c_prefijo || '%';

    IF v_n <> 0 THEN
        RAISE_APPLICATION_ERROR(-20999, 'ORACULO TSK-057: la limpieza del oraculo de concurrencia dejo ' || v_n || ' filas en aviso_correo');
    END IF;
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        -- La limpieza va envuelta para que un fallo suyo no enmascare el error original.
        BEGIN
            limpiar;
        EXCEPTION
            WHEN OTHERS THEN
                NULL;
        END;
        RAISE;
END;
